const SWARAJ_LOCATIONS=[{name:"Radhanagar Beach (Beach No. 7)",lat:11.982,lng:92.964,description:"Named Asia's Best Beach by Time magazine in 2004 and Blue Flag certified in 2020 — 2 km of white sand backed by forest, best known for its sunsets."},{name:"Elephant Beach",lat:12.0097,lng:92.9477,description:"The island's water-sports hub on the northwest coast, reached by boat or forest trek, with shallow coral gardens ideal for snorkelling."},{name:"Kalapathar Beach",lat:12.001,lng:93.033,description:"A quieter beach on the southeastern coast, named for the large black rocks along its white-sand shoreline — a favourite sunrise spot."},{name:"Govind Nagar Jetty & Market",lat:12.033,lng:92.986,description:"The island's main jetty, market and transport hub, connected to Port Blair and Shaheed Dweep (Neil Island) by regular ferries."},{name:"Nemo Reef",lat:12.02,lng:92.978,description:"A popular beginner-friendly dive and snorkel site near Govind Nagar, named for the clownfish that live among its coral."}],SWARAJ_GALLERY=[{src:"../../assets/travel_beaches.png",caption:"Radhanagar Beach, Swaraj Dweep"},{src:"../../assets/travel_islands.png",caption:"Coastline near Elephant Beach"},{src:"../../assets/travel_hidden.png",caption:"Lush forest interior, a short trek from the beaches"}],SWARAJ_FACTS=["Havelock Island was renamed Swaraj Dweep ('Independence Island') in December 2018, on the 75th anniversary of Netaji Subhas Chandra Bose hoisting the Indian flag at Port Blair.","Radhanagar Beach was named Asia's Best Beach by Time magazine in 2004 and earned international Blue Flag certification in 2020.","Swaraj Dweep offers access to more than 20 scuba diving sites, making it the most popular diving destination in the Andaman Islands.","The island's six villages are still home to descendants of Bengali refugee families resettled here after the Partition of India in 1947.","Elephant Beach gets its name from elephants once used in logging that would swim across to the beach — the island later became famous for Rajan, a beloved swimming elephant.","Underwater visibility around Swaraj Dweep can reach 15 to 30 metres during the October–May dive season.","Swaraj Dweep and neighbouring Shaheed Dweep (Neil Island) are both part of Ritchie's Archipelago and are connected to each other by daily ferries."];let map,currentGalleryIndex=0,factIndex=0;function initTabs(){const e=document.querySelectorAll(".swaraj-tab-btn"),t=document.querySelectorAll(".swaraj-tab-panel");e.forEach(a=>{a.addEventListener("click",()=>{const n=a.getAttribute("data-tab");e.forEach(e=>e.classList.remove("active")),a.classList.add("active"),t.forEach(e=>{e.classList.toggle("active",e.id==="tab-"+n)})})})}function initGallery(){const e=document.getElementById("swaraj-gallery-grid");e&&(e.innerHTML="",SWARAJ_GALLERY.forEach((t,a)=>{const n=document.createElement("figure");n.className="swaraj-gallery-item",n.innerHTML=`\n      <img src="${t.src}" alt="${t.caption}" loading="lazy">\n      <figcaption>${t.caption}</figcaption>\n    `,n.addEventListener("click",()=>openLightbox(a)),e.appendChild(n)}))}function initLightbox(){document.querySelectorAll("[data-close-lightbox]").forEach(e=>{e.addEventListener("click",closeLightbox)});const e=document.getElementById("swaraj-lightbox-prev"),t=document.getElementById("swaraj-lightbox-next");e&&e.addEventListener("click",()=>showGalleryImage(currentGalleryIndex-1)),t&&t.addEventListener("click",()=>showGalleryImage(currentGalleryIndex+1)),document.addEventListener("keydown",e=>{const t=document.getElementById("swaraj-lightbox");t&&!t.hidden&&("Escape"===e.key&&closeLightbox(),"ArrowRight"===e.key&&showGalleryImage(currentGalleryIndex+1),"ArrowLeft"===e.key&&showGalleryImage(currentGalleryIndex-1))})}function openLightbox(e){const t=document.getElementById("swaraj-lightbox");t&&(t.hidden=!1,document.body.style.overflow="hidden",showGalleryImage(e))}function closeLightbox(){const e=document.getElementById("swaraj-lightbox");e&&(e.hidden=!0,document.body.style.overflow="")}function showGalleryImage(e){const t=SWARAJ_GALLERY.length;currentGalleryIndex=(e+t)%t;const a=SWARAJ_GALLERY[currentGalleryIndex],n=document.getElementById("swaraj-lightbox-image"),o=document.getElementById("swaraj-lightbox-caption");n&&(n.src=a.src),n&&(n.alt=a.caption),o&&(o.textContent=a.caption)}function initFactsRotator(){const e=document.getElementById("swaraj-fact-text"),t=document.getElementById("swaraj-fact-dots");function a(a){factIndex=a,e.style.opacity="0",setTimeout(()=>{e.textContent=SWARAJ_FACTS[factIndex],e.style.opacity="1"},200),t&&[...t.children].forEach((e,t)=>e.classList.toggle("active",t===factIndex))}e&&(t&&SWARAJ_FACTS.forEach((e,n)=>{const o=document.createElement("button");o.className="swaraj-fact-dot"+(0===n?" active":""),o.setAttribute("aria-label","Show fact "+(n+1)),o.addEventListener("click",()=>a(n)),t.appendChild(o)}),a(0),setInterval(()=>a((factIndex+1)%SWARAJ_FACTS.length),6e3))}function initMap(){document.getElementById("swaraj-map")&&"undefined"!=typeof L&&(map=L.map("swaraj-map",{scrollWheelZoom:!1,minZoom:8}).setView([12,92.98],12),L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",{attribution:"&copy; OpenStreetMap contributors &copy; CARTO",maxZoom:18}).addTo(map),SWARAJ_LOCATIONS.forEach(e=>{L.circleMarker([e.lat,e.lng],{radius:8,color:"#ff9933",fillColor:"#ffb01f",fillOpacity:.85,weight:2}).addTo(map).bindPopup(`<strong>${e.name}</strong><br>${e.description}`)}))}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initGallery(),initFactsRotator(),initMap(),initLightbox()});